function oasisLanguage(hass) {
  const value=hass?.locale?.language || hass?.language || 'en';
  const language=String(value).toLowerCase().replaceAll('_','-').split('-')[0];
  return ['fr','en','de','es','it','hu','pt','id','zh','hi','bn','ar','ur'].includes(language)?language:'en';
}
function oasisTranslate(language,key,params={}) {
  if(typeof key!=='string')return String(key??'');
  const icon=/^([✈✕] )/.exec(key);
  if(icon)return icon[1]+oasisTranslate(language,key.slice(icon[1].length),params);
  const message=language==='fr'?key:(OASIS_TRANSLATIONS[key]?.[language] ?? OASIS_TRANSLATIONS[key]?.en ?? key);
  return message.replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??'{'+name+'}'));
}
function oasisStaticText(element,entries) {
  for(const [selector,key,attribute] of entries) {
    const node=element.shadowRoot.querySelector(selector);
    if(!node)continue;
    const value=element._t(key);
    if(attribute)node.setAttribute(attribute,value);else node.textContent=value;
  }
}

