    const query='SELECT ?cityLabel ?image WHERE { ?airport wdt:P239 "'+code+'"; wdt:P931 ?city. ?city wdt:P18 ?image. SERVICE wikibase:label { bd:serviceParam wikibase:language "fr,en". } } LIMIT 1';
